import socket, concurrent.futures, sys

def scan(target):
    ip, port = target
    s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    s.settimeout(0.25)
    try:
        if s.connect_ex((ip, port)) == 0:
            return (ip, port, True)
        return (ip, port, False)
    finally:
        s.close()

def main():
    ip = sys.argv[1]
    start, end = int(sys.argv[2]), int(sys.argv[3])
    ports = list(range(start, end+1))
    found = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=256) as ex:
        for ip_, port, ok in ex.map(scan, [(ip,p) for p in ports], chunksize=64):
            if ok:
                found.append(port)
    print(ip, "open:", sorted(found))

main()
